    if not re.fullmatch(full_pattern, s):
        raise ValueError("invalid duration format")
    # Extract all components (ignoring spaces) and compute total seconds.
    matches = re.finditer(r"(\d+)([dhmsDHMS])", s, flags=re.IGNORECASE)
    total_seconds = 0
