    for m in matches:
        number = int(m.group(1))
        unit_char = m.group(2).lower()
        # Duplicate unit check.
        if unit_char in seen_units:
            raise ValueError(f"duplicate unit '{unit_char}' in duration")
        # Order check: must be strictly increasing order (d, h, m, s).
        current_order = order_map[unit_char]
        if current_order <= last_order:
            raise ValueError("units not in decreasing order")
        seen_units.add(unit_char)
        last_order = current_order
        total_seconds += number * size_map[unit_char]
